// Advanced-mode Pages worker: serves the two JPEGs (the deploy tooling can only commit text),
// and hands every other request to the static assets (so _redirects and clean URLs still apply).
const IMAGES = {
  "/og-image.jpg": "",
  "/portrait.jpg": "",
};
const cache = {};
function bytes(path) {
  if (!cache[path]) {
    const bin = atob(IMAGES[path]);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    cache[path] = out;
  }
  return cache[path];
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (Object.prototype.hasOwnProperty.call(IMAGES, url.pathname)) {
      const body = request.method === "HEAD" ? null : bytes(url.pathname);
      return new Response(body, {
        headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=86400" },
      });
    }
    if (url.pathname.startsWith("/functions/") || url.pathname === "/_worker.js") {
      return new Response("Not found", { status: 404 });
    }
    return env.ASSETS.fetch(request);
  },
};
